 	if (reg & DW_UART_CPR_SIR_MODE)
 		up->capabilities |= UART_CAP_IRDA;
+
+	if (reg & DW_UART_CPR_SHADOW)
+		pd->shadow_support = true;
 }
 EXPORT_SYMBOL_GPL(dw8250_setup_port);
